package kr.co.farmerflood.trigger.service;
import java.util.*; import kr.co.farmerflood.trigger.domain.*; import kr.co.farmerflood.trigger.provider.*; import org.springframework.stereotype.Service;
@Service public class StationDashboardService {private final WaterStationCatalogue catalogue;private final WeatherForecastProvider weather;private final MockDemoStationService demos;public StationDashboardService(WaterStationCatalogue c,WeatherForecastProvider w,MockDemoStationService d){catalogue=c;weather=w;demos=d;}public List<StationSummary> stations(String district,boolean thresholdOnly){return java.util.stream.Stream.concat(demos.stations().stream(),catalogue.chungbukStations().stream()).filter(s->district==null||district.isBlank()||s.address().contains(district)).filter(s->!thresholdOnly||s.thresholds().complete()).toList();}public StationDetail detail(String code){if(demos.contains(code))return demos.detail(code);StationSummary s=catalogue.chungbukStations().stream().filter(x->x.stationCode().equals(code)).findFirst().orElseThrow(()->new NoSuchElementException("Unknown station: "+code));return new StationDetail(s,weather.timeline(s.nx(),s.ny(),24));}}
